    17→#include "eip7594/eip7594.h"
    18→#include "common/alloc.h"
    19→#include "common/fr.h"
    20→#include "common/lincomb.h"
    21→#include "common/utils.h"
    22→#include "eip7594/fft.h"
    23→#include "eip7594/fk20.h"
    24→#include "eip7594/poly.h"
    25→#include "eip7594/recovery.h"
    26→
    27→#include <assert.h> /* For assert */
    28→#include <string.h> /* For memcpy & strlen */
    29→
    30→////////////////////////////////////////////////////////////////////////////////////////////////////
    31→// Macros
    32→////////////////////////////////////////////////////////////////////////////////////////////////////
    33→
    34→/** Length of the domain string. */
    35→#define DOMAIN_STR_LENGTH 16
    36→
    37→////////////////////////////////////////////////////////////////////////////////////////////////////
    38→// Constants
    39→////////////////////////////////////////////////////////////////////////////////////////////////////
    40→
    41→/** The domain separator for verify_cell_kzg_proof_batch's random challenge. */
    42→static const char *RANDOM_CHALLENGE_DOMAIN_VERIFY_CELL_KZG_PROOF_BATCH = "RCKZGCBATCH__V1_";
    43→
    44→////////////////////////////////////////////////////////////////////////////////////////////////////
    45→// Compute
    46→////////////////////////////////////////////////////////////////////////////////////////////////////
    47→
    48→/**
    49→ * Given a blob, compute all of its cells and proofs.
    50→ *
    51→ * @param[out]  cells   An array of CELLS_PER_EXT_BLOB cells
    52→ * @param[out]  proofs  An array of CELLS_PER_EXT_BLOB proofs
    53→ * @param[in]   blob    The blob to get cells/proofs for
    54→ * @param[in]   s       The trusted setup
    55→ *
    56→ * @remark If cells is NULL, they won't be computed.
    57→ * @remark If proofs is NULL, they won't be computed.
    58→ * @remark Will return an error if both cells & proofs are NULL.
    59→ */
    60→C_KZG_RET compute_cells_and_kzg_proofs(
    61→    Cell *cells, KZGProof *proofs, const Blob *blob, const KZGSettings *s
    62→) {
    63→    C_KZG_RET ret;
    64→    fr_t *poly_monomial = NULL;
    65→    fr_t *poly_lagrange = NULL;
    66→    fr_t *data_fr = NULL;
    67→    g1_t *proofs_g1 = NULL;
    68→
    69→    /* If both of these are null, something is wrong */
    70→    if (cells == NULL && proofs == NULL) {
    71→        return C_KZG_BADARGS;
    72→    }
    73→
    74→    /* Allocate space fr-form arrays */
    75→    ret = new_fr_array(&poly_monomial, FIELD_ELEMENTS_PER_EXT_BLOB);
    76→    if (ret != C_KZG_OK) goto out;
    77→    ret = new_fr_array(&poly_lagrange, FIELD_ELEMENTS_PER_EXT_BLOB);
    78→    if (ret != C_KZG_OK) goto out;
    79→
    80→    /*
    81→     * Convert the blob to a polynomial in lagrange form. Note that only the first 4096 fields of
    82→     * the polynomial will be set. The upper 4096 fields will remain zero. The extra space is
    83→     * required because the polynomial will be evaluated to the extended domain (8192 roots of
    84→     * unity).
    85→     */
    86→    ret = blob_to_polynomial(poly_lagrange, blob);
    87→    if (ret != C_KZG_OK) goto out;
    88→
    89→    /* We need the polynomial to be in monomial form */
    90→    ret = poly_lagrange_to_monomial(poly_monomial, poly_lagrange, FIELD_ELEMENTS_PER_BLOB, s);
    91→    if (ret != C_KZG_OK) goto out;
    92→
    93→    /* Ensure that only the first FIELD_ELEMENTS_PER_BLOB elements can be non-zero */
    94→    for (size_t i = FIELD_ELEMENTS_PER_BLOB; i < FIELD_ELEMENTS_PER_EXT_BLOB; i++) {
    95→        assert(fr_equal(&poly_monomial[i], &FR_ZERO));
    96→    }
    97→
    98→    if (cells != NULL) {
    99→        /* Allocate space for our data points */
   100→        ret = new_fr_array(&data_fr, FIELD_ELEMENTS_PER_EXT_BLOB);
   101→        if (ret != C_KZG_OK) goto out;
   102→
   103→        /* Get the data points via forward transformation */
   104→        ret = fr_fft(data_fr, poly_monomial, FIELD_ELEMENTS_PER_EXT_BLOB, s);
   105→        if (ret != C_KZG_OK) goto out;
   106→
   107→        /* Bit-reverse the data points */
   108→        ret = bit_reversal_permutation(data_fr, sizeof(fr_t), FIELD_ELEMENTS_PER_EXT_BLOB);
   109→        if (ret != C_KZG_OK) goto out;
   110→
   111→        /* Convert all of the cells to byte-form */
   112→        for (size_t i = 0; i < CELLS_PER_EXT_BLOB; i++) {
   113→            for (size_t j = 0; j < FIELD_ELEMENTS_PER_CELL; j++) {
   114→                size_t index = i * FIELD_ELEMENTS_PER_CELL + j;
   115→                size_t offset = j * BYTES_PER_FIELD_ELEMENT;
   116→                bytes_from_bls_field((Bytes32 *)&cells[i].bytes[offset], &data_fr[index]);
   117→            }
   118→        }
   119→    }
   120→
   121→    if (proofs != NULL) {
   122→        /* Allocate space for our proofs in g1-form */
   123→        ret = new_g1_array(&proofs_g1, CELLS_PER_EXT_BLOB);
   124→        if (ret != C_KZG_OK) goto out;
   125→
   126→        /* Compute the proofs, only uses the first half of the polynomial */
   127→        ret = compute_fk20_cell_proofs(proofs_g1, poly_monomial, s);
   128→        if (ret != C_KZG_OK) goto out;
   129→
   130→        /* Bit-reverse the proofs */
   131→        ret = bit_reversal_permutation(proofs_g1, sizeof(g1_t), CELLS_PER_EXT_BLOB);
   132→        if (ret != C_KZG_OK) goto out;
   133→
   134→        /* Convert all of the proofs to byte-form */
   135→        for (size_t i = 0; i < CELLS_PER_EXT_BLOB; i++) {
   136→            bytes_from_g1(&proofs[i], &proofs_g1[i]);
   137→        }
   138→    }
   139→
   140→out:
   141→    c_kzg_free(poly_monomial);
   142→    c_kzg_free(poly_lagrange);
   143→    c_kzg_free(data_fr);
   144→    c_kzg_free(proofs_g1);
   145→    return ret;
   146→}
   147→
   148→////////////////////////////////////////////////////////////////////////////////////////////////////
   149→// Recover
   150→////////////////////////////////////////////////////////////////////////////////////////////////////
   151→
   152→/**
   153→ * Given some cells for a blob, recover all cells/proofs.
   154→ *
   155→ * @param[out]  recovered_cells     An array of CELLS_PER_EXT_BLOB cells
   156→ * @param[out]  recovered_proofs    An array of CELLS_PER_EXT_BLOB proofs
   157→ * @param[in]   cell_indices        The cell indices for the available cells, length `num_cells`
   158→ * @param[in]   cells               The available cells we recover from, length `num_cells`
   159→ * @param[in]   num_cells           The number of available cells provided
   160→ * @param[in]   s                   The trusted setup
   161→ *
   162→ * @remark At least CELLS_PER_BLOB cells must be provided.
   163→ * @remark Recovery is faster if there are fewer missing cells.
   164→ * @remark If recovered_proofs is NULL, they will not be recomputed.
   165→ */
   166→C_KZG_RET recover_cells_and_kzg_proofs(
   167→    Cell *recovered_cells,
   168→    KZGProof *recovered_proofs,
   169→    const uint64_t *cell_indices,
   170→    const Cell *cells,
   171→    uint64_t num_cells,
   172→    const KZGSettings *s
   173→) {
   174→    C_KZG_RET ret;
   175→    fr_t *recovered_cells_fr = NULL;
   176→    g1_t *recovered_proofs_g1 = NULL;
   177→
   178→    /* Ensure only one blob's worth of cells was provided */
   179→    if (num_cells > CELLS_PER_EXT_BLOB) {
   180→        ret = C_KZG_BADARGS;
   181→        goto out;
   182→    }
   183→
   184→    /* Check if it's possible to recover */
   185→    if (num_cells < CELLS_PER_BLOB) {
   186→        ret = C_KZG_BADARGS;
   187→        goto out;
   188→    }
   189→
   190→    for (size_t i = 0; i < num_cells; i++) {
   191→        /* Check that cell indices are valid */
   192→        if (cell_indices[i] >= CELLS_PER_EXT_BLOB) {
   193→            ret = C_KZG_BADARGS;
   194→            goto out;
   195→        }
   196→        /* Check that indices are in strictly ascending order */
   197→        if (i > 0 && cell_indices[i] <= cell_indices[i - 1]) {
   198→            ret = C_KZG_BADARGS;
   199→            goto out;
   200→        }
   201→    }
   202→
   203→    /* Do allocations */
   204→    ret = new_fr_array(&recovered_cells_fr, FIELD_ELEMENTS_PER_EXT_BLOB);
   205→    if (ret != C_KZG_OK) goto out;
   206→    ret = new_g1_array(&recovered_proofs_g1, CELLS_PER_EXT_BLOB);
   207→    if (ret != C_KZG_OK) goto out;
   208→
   209→    /* Initialize all cells as missing */
   210→    for (size_t i = 0; i < FIELD_ELEMENTS_PER_EXT_BLOB; i++) {
   211→        recovered_cells_fr[i] = FR_NULL;
   212→    }
   213→
   214→    /* Populate recovered_cells_fr with available cells at the right places */
   215→    for (size_t i = 0; i < num_cells; i++) {
   216→        size_t index = cell_indices[i] * FIELD_ELEMENTS_PER_CELL;
   217→        for (size_t j = 0; j < FIELD_ELEMENTS_PER_CELL; j++) {
   218→            /* Convert the untrusted input bytes to a field element */
   219→            fr_t *ptr = &recovered_cells_fr[index + j];
   220→            size_t offset = j * BYTES_PER_FIELD_ELEMENT;
   221→            ret = bytes_to_bls_field(ptr, (const Bytes32 *)&cells[i].bytes[offset]);
   222→            if (ret != C_KZG_OK) goto out;
   223→        }
   224→    }
   225→
   226→    if (num_cells == CELLS_PER_EXT_BLOB) {
   227→        /* Nothing to recover, copy the cells */
   228→        for (size_t i = 0; i < CELLS_PER_EXT_BLOB; i++) {
   229→            /*
   230→             * At this point, and based on our checks above, we know that all indices are in the
   231→             * right order. That is: cell_indices[i] == i
   232→             */
   233→            recovered_cells[i] = cells[i];
   234→        }
   235→    } else {
   236→        /* Perform cell recovery */
   237→        ret = recover_cells(recovered_cells_fr, cell_indices, num_cells, recovered_cells_fr, s);
   238→        if (ret != C_KZG_OK) goto out;
   239→
   240→        /* Convert the recovered data points to byte-form */
   241→        for (size_t i = 0; i < CELLS_PER_EXT_BLOB; i++) {
   242→            for (size_t j = 0; j < FIELD_ELEMENTS_PER_CELL; j++) {
   243→                size_t index = i * FIELD_ELEMENTS_PER_CELL + j;
   244→                size_t offset = j * BYTES_PER_FIELD_ELEMENT;
   245→                bytes_from_bls_field(
   246→                    (Bytes32 *)&recovered_cells[i].bytes[offset], &recovered_cells_fr[index]
   247→                );
   248→            }
   249→        }
   250→    }
   251→
   252→    if (recovered_proofs != NULL) {
   253→        /*
   254→         * Instead of converting the cells to a blob and back, we can just treat the cells as a
   255→         * polynomial. We are done with the fr-form recovered cells and we can safely mutate the
   256→         * array.
   257→         */
   258→        ret = poly_lagrange_to_monomial(
   259→            recovered_cells_fr, recovered_cells_fr, FIELD_ELEMENTS_PER_EXT_BLOB, s
   260→        );
   261→        if (ret != C_KZG_OK) goto out;
   262→
   263→        /* Compute the proofs, only uses the first half of the polynomial */
   264→        ret = compute_fk20_cell_proofs(recovered_proofs_g1, recovered_cells_fr, s);
   265→        if (ret != C_KZG_OK) goto out;
   266→
   267→        /* Bit-reverse the proofs */
   268→        ret = bit_reversal_permutation(recovered_proofs_g1, sizeof(g1_t), CELLS_PER_EXT_BLOB);
   269→        if (ret != C_KZG_OK) goto out;
   270→
   271→        /* Convert all of the proofs to byte-form */
   272→        for (size_t i = 0; i < CELLS_PER_EXT_BLOB; i++) {
   273→            bytes_from_g1(&recovered_proofs[i], &recovered_proofs_g1[i]);
   274→        }
   275→    }
   276→
   277→out:
   278→    c_kzg_free(recovered_cells_fr);
   279→    c_kzg_free(recovered_proofs_g1);
   280→    return ret;
   281→}
   282→
   283→////////////////////////////////////////////////////////////////////////////////////////////////////
   284→// Verify
   285→////////////////////////////////////////////////////////////////////////////////////////////////////
   286→
   287→/**
   288→ * Helper function to compare two commitments.
   289→ *
   290→ * @param[in]   a   The first commitment
   291→ * @param[in]   b   The second commitment
   292→ *
   293→ * @return True if the commitments are the same, otherwise false.
   294→ */
   295→static bool commitments_equal(const Bytes48 *a, const Bytes48 *b) {
   296→    return memcmp(a->bytes, b->bytes, BYTES_PER_COMMITMENT) == 0;
   297→}
   298→
   299→/**
   300→ * Helper function to copy one commitment's bytes to another.
   301→ *
   302→ * @param[in]   dst The destination commitment
   303→ * @param[in]   src The source commitment
   304→ */
   305→static void commitments_copy(Bytes48 *dst, const Bytes48 *src) {
   306→    memcpy(dst->bytes, src->bytes, BYTES_PER_COMMITMENT);
   307→}
   308→
   309→/**
   310→ * Convert a list of commitments with potential duplicates to a list of unique commitments. Also
   311→ * returns a list of indices which point to those new unique commitments.
   312→ *
   313→ * @param[in,out]   commitments_out Updated to only contain unique commitments
   314→ * @param[out]      indices_out     Used as map between old/new commitments
   315→ * @param[in,out]   count_out       Number of commitments before and after
   316→ *
   317→ * @remark The input arrays are re-used.
   318→ * @remark The number of commitments/indices must be the same.
   319→ * @remark The length of `indices_out` is unchanged.
   320→ * @remark `count_out` is updated to be the number of unique commitments.
   321→ */
   322→static void deduplicate_commitments(
   323→    Bytes48 *commitments_out, uint64_t *indices_out, size_t *count_out
   324→) {
   325→    /* Bail early if there are no commitments */
   326→    if (*count_out == 0) return;
   327→
   328→    /* The first commitment is always new */
   329→    indices_out[0] = 0;
   330→    size_t new_count = 1;
   331→
   332→    /* Create list of unique commitments & indices to them */
   333→    for (size_t i = 1; i < *count_out; i++) {
   334→        bool exist = false;
   335→        for (size_t j = 0; j < new_count; j++) {
   336→            if (commitments_equal(&commitments_out[i], &commitments_out[j])) {
   337→                /* This commitment already exists */
   338→                indices_out[i] = j;
   339→                exist = true;
   340→                break;
   341→            }
   342→        }
   343→        if (!exist) {
   344→            /* This is a new commitment */
   345→            commitments_copy(&commitments_out[new_count], &commitments_out[i]);
   346→            indices_out[i] = new_count;
   347→            new_count++;
   348→        }
   349→    }
   350→
   351→    /* Update the count */
   352→    *count_out = new_count;
   353→}
   354→
   355→/**
   356→ * Compute the challenge value used for batch verification of cell KZG proofs.
   357→ *
   358→ * @param[out]  challenge_out       The output challenge as a BLS field element
   359→ * @param[in]   commitments_bytes   The input commitments, length `num_commitments`
   360→ * @param[in]   num_commitments     The number of commitments
   361→ * @param[in]   commitment_indices  The cell commitment indices, length `num_cells`
   362→ * @param[in]   cell_indices        The cell indices, length `num_cells`
   363→ * @param[in]   cells               The cells, length `num_cells`
   364→ * @param[in]   proofs_bytes        The cell proofs, length `num_cells`
   365→ * @param[in]   num_cells           The number of cells
   366→ */
   367→C_KZG_RET compute_verify_cell_kzg_proof_batch_challenge(
   368→    fr_t *challenge_out,
   369→    const Bytes48 *commitments_bytes,
   370→    uint64_t num_commitments,
   371→    const uint64_t *commitment_indices,
   372→    const uint64_t *cell_indices,
   373→    const Cell *cells,
   374→    const Bytes48 *proofs_bytes,
   375→    uint64_t num_cells
   376→) {
   377→    C_KZG_RET ret;
   378→    uint8_t *bytes = NULL;
   379→    Bytes32 r_bytes;
   380→
   381→    /* Calculate the size of the data we're going to hash */
   382→    size_t input_size = DOMAIN_STR_LENGTH                          /* The domain separator */
   383→                        + sizeof(uint64_t)                         /* FIELD_ELEMENTS_PER_BLOB */
   384→                        + sizeof(uint64_t)                         /* FIELD_ELEMENTS_PER_CELL */
   385→                        + sizeof(uint64_t)                         /* num_commitments */
   386→                        + sizeof(uint64_t)                         /* num_cells */
   387→                        + (num_commitments * BYTES_PER_COMMITMENT) /* commitment_bytes */
   388→                        + (num_cells * sizeof(uint64_t))           /* commitment_indices */
   389→                        + (num_cells * sizeof(uint64_t))           /* cell_indices */
   390→                        + (num_cells * BYTES_PER_CELL)             /* cells */
   391→                        + (num_cells * BYTES_PER_PROOF);           /* proofs_bytes */
   392→
   393→    /* Allocate space to copy this data into */
   394→    ret = c_kzg_malloc((void **)&bytes, input_size);
   395→    if (ret != C_KZG_OK) goto out;
   396→
   397→    /* Pointer tracking `bytes` for writing on top of it */
   398→    uint8_t *offset = bytes;
   399→
   400→    /* Ensure that the domain string is the correct length */
   401→    assert(strlen(RANDOM_CHALLENGE_DOMAIN_VERIFY_CELL_KZG_PROOF_BATCH) == DOMAIN_STR_LENGTH);
   402→
   403→    /* Copy domain separator */
   404→    memcpy(offset, RANDOM_CHALLENGE_DOMAIN_VERIFY_CELL_KZG_PROOF_BATCH, DOMAIN_STR_LENGTH);
   405→    offset += DOMAIN_STR_LENGTH;
   406→
   407→    /* Copy field elements per blob */
   408→    bytes_from_uint64(offset, FIELD_ELEMENTS_PER_BLOB);
   409→    offset += sizeof(uint64_t);
   410→
   411→    /* Copy field elements per cell */
   412→    bytes_from_uint64(offset, FIELD_ELEMENTS_PER_CELL);
   413→    offset += sizeof(uint64_t);
   414→
   415→    /* Copy number of commitments */
   416→    bytes_from_uint64(offset, num_commitments);
   417→    offset += sizeof(uint64_t);
   418→
   419→    /* Copy number of cells */
   420→    bytes_from_uint64(offset, num_cells);
   421→    offset += sizeof(uint64_t);
   422→
   423→    for (size_t i = 0; i < num_commitments; i++) {
   424→        /* Copy commitment */
   425→        memcpy(offset, &commitments_bytes[i], BYTES_PER_COMMITMENT);
   426→        offset += BYTES_PER_COMMITMENT;
   427→    }
   428→
   429→    for (size_t i = 0; i < num_cells; i++) {
   430→        /* Copy row id */
   431→        bytes_from_uint64(offset, commitment_indices[i]);
   432→        offset += sizeof(uint64_t);
   433→
   434→        /* Copy column id */
   435→        bytes_from_uint64(offset, cell_indices[i]);
   436→        offset += sizeof(uint64_t);
   437→
   438→        /* Copy cell */
   439→        memcpy(offset, &cells[i], BYTES_PER_CELL);
   440→        offset += BYTES_PER_CELL;
   441→
   442→        /* Copy proof */
   443→        memcpy(offset, &proofs_bytes[i], BYTES_PER_PROOF);
   444→        offset += BYTES_PER_PROOF;
   445→    }
   446→
   447→    /* Make sure we wrote the entire buffer */
   448→    assert(offset == bytes + input_size);
   449→
   450→    /* Create the challenge hash */
   451→    blst_sha256(r_bytes.bytes, bytes, input_size);
   452→
   453→    /* Convert to BLS field element */
   454→    hash_to_bls_field(challenge_out, &r_bytes);
   455→
   456→out:
   457→    c_kzg_free(bytes);
   458→    return ret;
   459→}
   460→
   461→/**
   462→ * Compute the sum of the commitments weighted by the powers of r.
   463→ *
   464→ * @param[out]  sum_of_commitments_out  The resulting G1 sum of the commitments
   465→ * @param[in]   unique_commitments      Array of unique commitments, length `num_commitments`
   466→ * @param[in]   commitment_indices      Indices mapping to unique commitments, length `num_cells`
   467→ * @param[in]   r_powers                Array of powers of r used for weighting, length `num_cells`
   468→ * @param[in]   num_commitments         The number of unique commitments
   469→ * @param[in]   num_cells               The number of cells
   470→ */
   471→static C_KZG_RET compute_weighted_sum_of_commitments(
   472→    g1_t *sum_of_commitments_out,
   473→    const Bytes48 *unique_commitments,
   474→    const uint64_t *commitment_indices,
   475→    const fr_t *r_powers,
   476→    size_t num_commitments,
   477→    uint64_t num_cells
   478→) {
   479→    C_KZG_RET ret;
   480→    g1_t *commitments_g1 = NULL;
   481→    fr_t *commitment_weights = NULL;
   482→
   483→    ret = new_fr_array(&commitment_weights, num_commitments);
   484→    if (ret != C_KZG_OK) goto out;
   485→    ret = new_g1_array(&commitments_g1, num_commitments);
   486→    if (ret != C_KZG_OK) goto out;
   487→
   488→    for (size_t i = 0; i < num_commitments; i++) {
   489→        /* Convert & validate commitment */
   490→        ret = bytes_to_kzg_commitment(&commitments_g1[i], &unique_commitments[i]);
   491→        if (ret != C_KZG_OK) goto out;
   492→
   493→        /* Initialize the weight to zero */
   494→        commitment_weights[i] = FR_ZERO;
   495→    }
   496→
   497→    /* Update commitment weights */
   498→    for (uint64_t i = 0; i < num_cells; i++) {
   499→        blst_fr_add(
   500→            &commitment_weights[commitment_indices[i]],
   501→            &commitment_weights[commitment_indices[i]],
   502→            &r_powers[i]
   503→        );
   504→    }
   505→
   506→    /* Compute commitment sum */
   507→    ret = g1_lincomb_fast(
   508→        sum_of_commitments_out, commitments_g1, commitment_weights, num_commitments
   509→    );
   510→    if (ret != C_KZG_OK) goto out;
   511→
   512→out:
   513→    c_kzg_free(commitment_weights);
   514→    c_kzg_free(commitments_g1);
   515→    return ret;
   516→}
   517→
   518→/**
   519→ * Compute the inverse coset factor h_k^{-1},
   520→ *  where `h_k` is the coset factor for cell with index `k`.
   521→ *
   522→ * @param[out]  inv_coset_factor_out    Pointer to store the computed inverse coset factor
   523→ * @param[in]   cell_index              The index of the cell
   524→ * @param[in]   s                       The trusted setup
   525→ */
   526→static void get_inv_coset_shift_for_cell(
   527→    fr_t *inv_coset_factor_out, uint64_t cell_index, const KZGSettings *s
   528→) {
   529→    /*
   530→     * Get the cell index in reverse-bit order.
   531→     * This index points to this cell's coset factor h_k in the roots_of_unity array.
   532→     */
   533→    uint64_t cell_idx_rbl = reverse_bits_limited(CELLS_PER_EXT_BLOB, cell_index);
   534→
   535→    /*
   536→     * Observe that for every element in roots_of_unity, we can find its inverse by
   537→     * accessing its reflected element.
   538→     *
   539→     * For example, consider a multiplicative subgroup with eight elements:
   540→     *   roots = {w^0, w^1, w^2, ... w^7, w^0}
   541→     * For a root of unity in roots[i], we can find its inverse in roots[-i].
   542→     */
   543→    assert(cell_idx_rbl <= FIELD_ELEMENTS_PER_EXT_BLOB);
   544→    uint64_t inv_coset_factor_idx = FIELD_ELEMENTS_PER_EXT_BLOB - cell_idx_rbl;
   545→
   546→    /* Get h_k^{-1} using the index */
   547→    assert(inv_coset_factor_idx < FIELD_ELEMENTS_PER_EXT_BLOB + 1);
   548→    *inv_coset_factor_out = s->roots_of_unity[inv_coset_factor_idx];
   549→}
   550→
   551→/**
   552→ * Compute h_k^{n}, where `h_k` is the coset factor for cell with index `k`.
   553→ *
   554→ * @param[out]  coset_factor_out    Pointer to store h_k^{n}
   555→ * @param[in]   cell_index          The index of the cell
   556→ * @param[in]   s                   The trusted setup
   557→ */
   558→static void get_coset_shift_pow_for_cell(
   559→    fr_t *coset_factor_out, uint64_t cell_index, const KZGSettings *s
   560→) {
   561→    /*
   562→     * Get the cell index in reverse-bit order.
   563→     * This index points to this cell's coset factor h_k in the roots_of_unity array.
   564→     */
   565→    uint64_t cell_idx_rbl = reverse_bits_limited(CELLS_PER_EXT_BLOB, cell_index);
   566→
   567→    /*
   568→     * Get the index to h_k^n in the roots_of_unity array.
   569→     *
   570→     * Multiplying the index of h_k by n, effectively raises h_k to the n-th power,
   571→     * because advancing in the roots_of_unity array corresponds to increasing exponents.
   572→     */
   573→    uint64_t h_k_pow_idx = cell_idx_rbl * FIELD_ELEMENTS_PER_CELL;
   574→
   575→    /* Get h_k^n using the index */
   576→    assert(h_k_pow_idx < FIELD_ELEMENTS_PER_EXT_BLOB + 1);
   577→    *coset_factor_out = s->roots_of_unity[h_k_pow_idx];
   578→}
   579→
   580→/**
   581→ * Aggregate columns, compute the sum of interpolation polynomials, and commit to the result.
   582→ *
   583→ * This function computes `RLI = [sum_k r^k interpolation_poly_k(s)]` from the spec.
   584→ *
   585→ * @param[out]  commitment_out  Commitment to the aggregated interpolation poly
   586→ * @param[in]   r_powers        Precomputed powers of the random challenge, length `num_cells`
   587→ * @param[in]   cell_indices    Indices of the cells, length `num_cells`
   588→ * @param[in]   cells           Array of cells, length `num_cells`
   589→ * @param[in]   num_cells       Number of cells
   590→ * @param[in]   s               The trusted setup
   591→ */
   592→static C_KZG_RET compute_commitment_to_aggregated_interpolation_poly(
   593→    g1_t *commitment_out,
   594→    const fr_t *r_powers,
   595→    const uint64_t *cell_indices,
   596→    const Cell *cells,
   597→    uint64_t num_cells,
   598→    const KZGSettings *s
   599→) {
   600→    C_KZG_RET ret;
   601→    bool *is_cell_used = NULL;
   602→    fr_t *aggregated_column_cells = NULL;
   603→    fr_t *column_interpolation_poly = NULL;
   604→    fr_t *aggregated_interpolation_poly = NULL;
   605→
   606→    ////////////////////////////////////////////////////////////////////////////////////////////////
   607→    // Array allocations
   608→    ////////////////////////////////////////////////////////////////////////////////////////////////
   609→
   610→    ret = new_bool_array(&is_cell_used, CELLS_PER_EXT_BLOB);
   611→    if (ret != C_KZG_OK) goto out;
   612→    ret = new_fr_array(&aggregated_column_cells, FIELD_ELEMENTS_PER_EXT_BLOB);
   613→    if (ret != C_KZG_OK) goto out;
   614→    ret = new_fr_array(&column_interpolation_poly, FIELD_ELEMENTS_PER_CELL);
   615→    if (ret != C_KZG_OK) goto out;
   616→    ret = new_fr_array(&aggregated_interpolation_poly, FIELD_ELEMENTS_PER_CELL);
   617→    if (ret != C_KZG_OK) goto out;
   618→
   619→    ////////////////////////////////////////////////////////////////////////////////////////////////
   620→    // Aggregate cells from the same column
   621→    ////////////////////////////////////////////////////////////////////////////////////////////////
   622→
   623→    /* Start with zeroed out columns */
   624→    for (size_t i = 0; i < CELLS_PER_EXT_BLOB; i++) {
   625→        for (size_t j = 0; j < FIELD_ELEMENTS_PER_CELL; j++) {
   626→            size_t index = i * FIELD_ELEMENTS_PER_CELL + j;
   627→            aggregated_column_cells[index] = FR_ZERO;
   628→        }
   629→    }
   630→
   631→    /*
   632→     * Vertically collapse cells of the 2D matrix into a single array: `aggregated_column_cells`.
   633→     *
   634→     * For each provided cell, go over its field elements, and scale them by the appropriate power
   635→     * of r. Then aggregate all field elements on the same vertical slice into a single array.
   636→     */
   637→    for (uint64_t cell_index = 0; cell_index < num_cells; cell_index++) {
   638→        /* Determine which column this cell belongs to */
   639→        uint64_t column_index = cell_indices[cell_index];
   640→
   641→        /* Iterate over every field element of this cell: scale it and aggregate it */
   642→        for (size_t fr_index = 0; fr_index < FIELD_ELEMENTS_PER_CELL; fr_index++) {
   643→            fr_t original_fr, scaled_fr;
   644→
   645→            /* Get the field element at this offset */
   646→            size_t offset = fr_index * BYTES_PER_FIELD_ELEMENT;
   647→            ret = bytes_to_bls_field(
   648→                &original_fr, (const Bytes32 *)&cells[cell_index].bytes[offset]
   649→            );
   650→            if (ret != C_KZG_OK) goto out;
   651→
   652→            /* Scale the field element by the appropriate power of r */
   653→            blst_fr_mul(&scaled_fr, &original_fr, &r_powers[cell_index]);
   654→
   655→            /* Figure out the right index for this field element within the extended array */
   656→            size_t array_index = column_index * FIELD_ELEMENTS_PER_CELL + fr_index;
   657→            /* Aggregate the scaled field element into the array */
   658→            blst_fr_add(
   659→                &aggregated_column_cells[array_index],
   660→                &aggregated_column_cells[array_index],
   661→                &scaled_fr
   662→            );
   663→        }
   664→    }
   665→
   666→    ////////////////////////////////////////////////////////////////////////////////////////////////
   667→    // Determine which cells are used
   668→    ////////////////////////////////////////////////////////////////////////////////////////////////
   669→
   670→    /* Start with false values */
   671→    for (size_t i = 0; i < CELLS_PER_EXT_BLOB; i++) {
   672→        is_cell_used[i] = false;
   673→    }
   674→
   675→    /* Mark each cell index as used */
   676→    for (uint64_t i = 0; i < num_cells; i++) {
   677→        is_cell_used[cell_indices[i]] = true;
   678→    }
   679→
   680→    ////////////////////////////////////////////////////////////////////////////////////////////////
   681→    // Compute interpolation polynomials using the aggregated cells
   682→    ////////////////////////////////////////////////////////////////////////////////////////////////
   683→
   684→    /* Start with a zeroed out poly */
   685→    for (size_t i = 0; i < FIELD_ELEMENTS_PER_CELL; i++) {
   686→        aggregated_interpolation_poly[i] = FR_ZERO;
   687→    }
   688→
   689→    /* Interpolate each column */
   690→    for (size_t i = 0; i < CELLS_PER_EXT_BLOB; i++) {
   691→        /* We can skip columns without any cells */
   692→        if (!is_cell_used[i]) continue;
   693→
   694→        /* Offset to the first cell for this column */
   695→        size_t index = i * FIELD_ELEMENTS_PER_CELL;
   696→
   697→        /*
   698→         * Reach into the big array and permute the right column.
   699→         * No need to copy the data, we are not gonna use them again.
   700→         */
   701→        ret = bit_reversal_permutation(
   702→            &aggregated_column_cells[index], sizeof(fr_t), FIELD_ELEMENTS_PER_CELL
   703→        );
   704→        if (ret != C_KZG_OK) goto out;
   705→
   706→        /*
   707→         * Get interpolation polynomial for this column. To do so we first do an IDFT over the roots
   708→         * of unity and then we scale the coefficients by the coset factor. We can't do an IDFT
   709→         * directly over the coset because it's not a subgroup.
   710→         */
   711→        ret = fr_ifft(
   712→            column_interpolation_poly, &aggregated_column_cells[index], FIELD_ELEMENTS_PER_CELL, s
   713→        );
   714→        if (ret != C_KZG_OK) goto out;
   715→
   716→        /* Shift the poly by h_k^{-1} where h_k is the coset factor for this cell */
   717→        fr_t inv_coset_factor;
   718→        get_inv_coset_shift_for_cell(&inv_coset_factor, i, s);
   719→        shift_poly(column_interpolation_poly, FIELD_ELEMENTS_PER_CELL, &inv_coset_factor);
   720→
   721→        /* Update the aggregated poly */
   722→        for (size_t k = 0; k < FIELD_ELEMENTS_PER_CELL; k++) {
   723→            blst_fr_add(
   724→                &aggregated_interpolation_poly[k],
   725→                &aggregated_interpolation_poly[k],
   726→                &column_interpolation_poly[k]
   727→            );
   728→        }
   729→    }
   730→
   731→    ////////////////////////////////////////////////////////////////////////////////////////////////
   732→    // Commit to the aggregated interpolation polynomial
   733→    ////////////////////////////////////////////////////////////////////////////////////////////////
   734→
   735→    ret = g1_lincomb_fast(
   736→        commitment_out,
   737→        s->g1_values_monomial,
   738→        aggregated_interpolation_poly,
   739→        FIELD_ELEMENTS_PER_CELL
   740→    );
   741→    if (ret != C_KZG_OK) goto out;
   742→
   743→out:
   744→    c_kzg_free(is_cell_used);
   745→    c_kzg_free(aggregated_column_cells);
   746→    c_kzg_free(column_interpolation_poly);
   747→    c_kzg_free(aggregated_interpolation_poly);
   748→    return ret;
   749→}
   750→
   751→/**
   752→ * Compute weighted sum of proofs.
   753→ *
   754→ * @param[out]  weighted_proof_lincomb  The resulting G1 sum of the proofs scaled by coset factors
   755→ * @param[in]   proofs_g1               Array of proofs, length `num_cells`
   756→ * @param[in]   r_powers                Array of powers of r used for weighting, length `num_cells`
   757→ * @param[in]   cell_indices            Array of cell indices, length `num_cells`
   758→ * @param[in]   num_cells               The number of cells
   759→ * @param[in]   s                       The trusted setup
   760→ */
   761→static C_KZG_RET computed_weighted_sum_of_proofs(
   762→    g1_t *weighted_proof_sum_out,
   763→    const g1_t *proofs_g1,
   764→    const fr_t *r_powers,
   765→    const uint64_t *cell_indices,
   766→    uint64_t num_cells,
   767→    const KZGSettings *s
   768→) {
   769→    C_KZG_RET ret;
   770→    fr_t *weighted_powers_of_r = NULL;
   771→
   772→    ret = new_fr_array(&weighted_powers_of_r, num_cells);
   773→    if (ret != C_KZG_OK) goto out;
   774→
   775→    for (uint64_t i = 0; i < num_cells; i++) {
   776→        /* Get scaling factor h_k^n where h_k is the coset factor for this cell */
   777→        fr_t h_k_pow;
   778→        get_coset_shift_pow_for_cell(&h_k_pow, cell_indices[i], s);
   779→
   780→        /* Scale the power of r by h_k^n */
   781→        blst_fr_mul(&weighted_powers_of_r[i], &r_powers[i], &h_k_pow);
   782→    }
   783→
   784→    ret = g1_lincomb_fast(weighted_proof_sum_out, proofs_g1, weighted_powers_of_r, num_cells);
   785→
   786→out:
   787→    c_kzg_free(weighted_powers_of_r);
   788→    return ret;
   789→}
   790→
   791→/**
   792→ * Given some cells, verify that their proofs are valid.
   793→ *
   794→ * @param[out]  ok                  True if the proofs are valid
   795→ * @param[in]   commitments_bytes   The commitments for the cells, length `num_cells`
   796→ * @param[in]   cell_indices        The indices for the cells, length `num_cells`
   797→ * @param[in]   cells               The cells to check, length `num_cells`
   798→ * @param[in]   proofs_bytes        The proofs for the cells, length `num_cells`
   799→ * @param[in]   num_cells           The number of cells provided
   800→ * @param[in]   s                   The trusted setup
   801→ */
   802→C_KZG_RET verify_cell_kzg_proof_batch(
   803→    bool *ok,
   804→    const Bytes48 *commitments_bytes,
   805→    const uint64_t *cell_indices,
   806→    const Cell *cells,
   807→    const Bytes48 *proofs_bytes,
   808→    uint64_t num_cells,
   809→    const KZGSettings *s
   810→) {
   811→    C_KZG_RET ret;
   812→    fr_t r;
   813→    g1_t interpolation_poly_commit;
   814→    g1_t final_g1_sum;
   815→    g1_t proof_lincomb;
   816→    g1_t weighted_sum_of_proofs;
   817→    g2_t power_of_s = s->g2_values_monomial[FIELD_ELEMENTS_PER_CELL];
   818→    size_t num_commitments;
   819→
   820→    /* Arrays */
   821→    Bytes48 *unique_commitments = NULL;
   822→    uint64_t *commitment_indices = NULL;
   823→    fr_t *r_powers = NULL;
   824→    g1_t *proofs_g1 = NULL;
   825→
   826→    *ok = false;
   827→
   828→    /* Exit early if we are given zero cells */
   829→    if (num_cells == 0) {
   830→        *ok = true;
   831→        return C_KZG_OK;
   832→    }
   833→
   834→    ////////////////////////////////////////////////////////////////////////////////////////////////
   835→    // Sanity checks
   836→    ////////////////////////////////////////////////////////////////////////////////////////////////
   837→
   838→    for (size_t i = 0; i < num_cells; i++) {
   839→        /* Make sure column index is valid */
   840→        if (cell_indices[i] >= CELLS_PER_EXT_BLOB) return C_KZG_BADARGS;
   841→    }
   842→
   843→    ////////////////////////////////////////////////////////////////////////////////////////////////
   844→    // Deduplicate commitments
   845→    ////////////////////////////////////////////////////////////////////////////////////////////////
   846→
   847→    ret = c_kzg_calloc((void **)&unique_commitments, num_cells, sizeof(Bytes48));
   848→    if (ret != C_KZG_OK) goto out;
   849→    ret = c_kzg_calloc((void **)&commitment_indices, num_cells, sizeof(uint64_t));
   850→    if (ret != C_KZG_OK) goto out;
   851→
   852→    /*
   853→     * Convert the array of cell commitments to an array of unique commitments and an array of
   854→     * indices to those unique commitments. We do this before the array allocations section below
   855→     * because we need to know how many commitment weights there will be.
   856→     */
   857→    num_commitments = num_cells;
   858→    memcpy(unique_commitments, commitments_bytes, num_cells * sizeof(Bytes48));
   859→    deduplicate_commitments(unique_commitments, commitment_indices, &num_commitments);
   860→
   861→    ////////////////////////////////////////////////////////////////////////////////////////////////
   862→    // Array allocations
   863→    ////////////////////////////////////////////////////////////////////////////////////////////////
   864→
   865→    ret = new_fr_array(&r_powers, num_cells);
   866→    if (ret != C_KZG_OK) goto out;
   867→    ret = new_g1_array(&proofs_g1, num_cells);
   868→    if (ret != C_KZG_OK) goto out;
   869→
   870→    ////////////////////////////////////////////////////////////////////////////////////////////////
   871→    // Compute powers of r, and extract KZG proofs out of input bytes
   872→    ////////////////////////////////////////////////////////////////////////////////////////////////
   873→
   874→    /* Compute the challenge */
   875→    ret = compute_verify_cell_kzg_proof_batch_challenge(
   876→        &r,
   877→        commitments_bytes,
   878→        num_commitments,
   879→        commitment_indices,
   880→        cell_indices,
   881→        cells,
   882→        proofs_bytes,
   883→        num_cells
   884→    );
   885→    if (ret != C_KZG_OK) goto out;
   886→
   887→    /*
   888→     * Derive random factors for the linear combination. The exponents start with 0. That is, they
   889→     * are r^0, r^1, r^2, r^3, and so on.
   890→     */
   891→    compute_powers(r_powers, &r, num_cells);
   892→
   893→    /* There should be a proof for each cell */
   894→    for (size_t i = 0; i < num_cells; i++) {
   895→        ret = bytes_to_kzg_proof(&proofs_g1[i], &proofs_bytes[i]);
   896→        if (ret != C_KZG_OK) goto out;
   897→    }
   898→
   899→    ////////////////////////////////////////////////////////////////////////////////////////////////
   900→    // Compute random linear combination of the proofs
   901→    ////////////////////////////////////////////////////////////////////////////////////////////////
   902→
   903→    ret = g1_lincomb_fast(&proof_lincomb, proofs_g1, r_powers, num_cells);
   904→    if (ret != C_KZG_OK) goto out;
   905→
   906→    ////////////////////////////////////////////////////////////////////////////////////////////////
   907→    // Compute sum of the commitments
   908→    ////////////////////////////////////////////////////////////////////////////////////////////////
   909→
   910→    ret = compute_weighted_sum_of_commitments(
   911→        &final_g1_sum, unique_commitments, commitment_indices, r_powers, num_commitments, num_cells
   912→    );
   913→    if (ret != C_KZG_OK) goto out;
   914→
   915→    ////////////////////////////////////////////////////////////////////////////////////////////////
   916→    // Commit to aggregated interpolation polynomial
   917→    ////////////////////////////////////////////////////////////////////////////////////////////////
   918→
   919→    /* Aggregate cells from same columns, sum interpolation polynomials, and commit */
   920→    ret = compute_commitment_to_aggregated_interpolation_poly(
   921→        &interpolation_poly_commit, r_powers, cell_indices, cells, num_cells, s
   922→    );
   923→    if (ret != C_KZG_OK) goto out;
   924→
   925→    /* Subtract commitment from sum by adding the negated commitment */
   926→    blst_p1_cneg(&interpolation_poly_commit, true);
   927→    blst_p1_add(&final_g1_sum, &final_g1_sum, &interpolation_poly_commit);
   928→
   929→    ////////////////////////////////////////////////////////////////////////////////////////////////
   930→    // Compute sum of the proofs scaled by the coset factors
   931→    ////////////////////////////////////////////////////////////////////////////////////////////////
   932→
   933→    ret = computed_weighted_sum_of_proofs(
   934→        &weighted_sum_of_proofs, proofs_g1, r_powers, cell_indices, num_cells, s
   935→    );
   936→    if (ret != C_KZG_OK) goto out;
   937→
   938→    blst_p1_add(&final_g1_sum, &final_g1_sum, &weighted_sum_of_proofs);
   939→
   940→    ////////////////////////////////////////////////////////////////////////////////////////////////
   941→    // Do the final pairing check
   942→    ////////////////////////////////////////////////////////////////////////////////////////////////
   943→
   944→    *ok = pairings_verify(&final_g1_sum, blst_p2_generator(), &proof_lincomb, &power_of_s);
   945→
   946→out:
   947→    c_kzg_free(unique_commitments);
   948→    c_kzg_free(commitment_indices);
   949→    c_kzg_free(r_powers);
   950→    c_kzg_free(proofs_g1);
   951→    return ret;
   952→}
   953→

